/**
 * R-1851 — share capital (company_share_capital) + shareholders (company_shareholders) and
 * their RPCs (migration 20261024202000_r1851_share_capital.sql). Writes only through the RPCs,
 * which check the role, the company, the business type and the authorised-capital limit.
 *
 * Untyped client: the tables and functions are newer than database.types.ts (shared,
 * regenerated by the manager after the migration lands).
 */
"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { SupabaseClient } from "@supabase/supabase-js";
import { toast } from "sonner";

import { createClient } from "@/lib/supabase/client";
import { useCurrentUser } from "@/lib/hooks/useCurrentUser";
import { toastError } from "@/lib/errors/toast-error";
import type { ShareCapital, Shareholder } from "@/lib/company/share-capital";

const untyped = () => createClient() as unknown as SupabaseClient;

export const SHARE_CAPITAL_KEY = ["share_capital"] as const;

/** Code deployed before the migration: nothing to show, the screens still work. */
export function isShareCapitalTableMissing(err: unknown): boolean {
  const m = err instanceof Error ? err.message : String(err ?? "");
  return /company_share(_capital|holders)/.test(m) && /(does not exist|could not find|schema cache)/i.test(m);
}

export interface ShareCapitalData {
  capital: ShareCapital | null;
  holders: Shareholder[];
}

/** The capital row + every shareholder, by name. A failed read is an error. */
export function useShareCapital(enabled = true) {
  const me = useCurrentUser();
  const tenantId = me.data?.tenantId ?? null;
  return useQuery({
    queryKey: [...SHARE_CAPITAL_KEY, tenantId],
    enabled: enabled && Boolean(tenantId),
    queryFn: async (): Promise<ShareCapitalData> => {
      const db = untyped();
      const [cap, holders] = await Promise.all([
        db.from("company_share_capital").select("authorised_capital, face_value").maybeSingle(),
        db.from("company_shareholders").select("id, name, pan, shares, allotted_on").order("name", { ascending: true }),
      ]);
      const err = cap.error ?? holders.error;
      if (err) {
        if (isShareCapitalTableMissing(err.message)) return { capital: null, holders: [] };
        throw new Error(err.message);
      }
      const c = cap.data as { authorised_capital: number | string; face_value: number | string } | null;
      return {
        capital: c ? { authorised_capital: Number(c.authorised_capital), face_value: Number(c.face_value) } : null,
        holders: ((holders.data ?? []) as Shareholder[]).map((h) => ({ ...h, shares: Number(h.shares) })),
      };
    },
  });
}

function invalidate(qc: ReturnType<typeof useQueryClient>) {
  void qc.invalidateQueries({ queryKey: SHARE_CAPITAL_KEY });
  void qc.invalidateQueries({ queryKey: ["balance-sheet"] });
}

export function useSaveShareCapital() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: ShareCapital) => {
      const { error } = await untyped().rpc("save_share_capital", {
        p_authorised_capital: input.authorised_capital,
        p_face_value: input.face_value,
      });
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      invalidate(qc);
      toast.success("Share capital saved");
    },
    onError: (err) => toastError(err, { fallback: "Couldn't save the share capital" }),
  });
}

export function useSaveShareholder() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: Omit<Shareholder, "id"> & { id: string | null }) => {
      const { data, error } = await untyped().rpc("save_shareholder", {
        p_id: input.id,
        p_name: input.name,
        p_pan: input.pan,
        p_shares: input.shares,
        p_allotted_on: input.allotted_on,
      });
      if (error) throw new Error(error.message);
      return data as string;
    },
    onSuccess: (_d, input) => {
      invalidate(qc);
      toast.success(input.id ? `${input.name} updated` : `${input.name} added to the shareholders`);
    },
    onError: (err) => toastError(err, { fallback: "Couldn't save the shareholder" }),
  });
}

export function useDeleteShareholder() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (id: string) => {
      const { error } = await untyped().rpc("delete_shareholder", { p_id: id });
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      invalidate(qc);
      toast.success("Shareholder removed");
    },
    onError: (err) => toastError(err, { fallback: "Couldn't remove the shareholder" }),
  });
}
